/**
 * RSS 2.0 and Atom parsing with the same discipline as the regional news
 * feed (server/providers/regional/news.js): regular expressions over a
 * bounded text, entities decoded, markup stripped, every link checked to be
 * http(s), duplicates dropped. No XML parser, no entity expansion.
 *
 * Some agency feeds are generated by CMS views rather than written as RSS:
 * titles, links and GUIDs wrapped in an `<a href>` with a relative address,
 * escaped markup inside descriptions, and long-form local dates without an
 * offset. Those are read too: the anchor's address is resolved against the
 * feed's `xml:base` (or its own address) and a local date is read in the
 * zone the caller names.
 */
import { parseLongLocalDate } from './time.js';

const NAMED_ENTITIES = Object.freeze({
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
});

function decodeEntities(text) {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (all, name) => {
    if (name[0] === '#') {
      const hex = name[1] === 'x' || name[1] === 'X';
      const code = parseInt(name.slice(hex ? 2 : 1), hex ? 16 : 10);
      return Number.isFinite(code) && code > 0 && code < 0x110000
        ? String.fromCodePoint(code)
        : ' ';
    }
    return NAMED_ENTITIES[name.toLowerCase()] ?? all;
  });
}

/** An HTML tag once escaped markup is decoded; `a < b` is not one. */
const DECODED_TAG = /<\/?[a-z][a-z0-9-]*(?:\s[^>]*)?\/?>/gi;

/**
 * Decode text from an RSS/Atom element: CDATA, markup, entities and
 * whitespace. Markup that arrives escaped once or twice (`&lt;a …&gt;`,
 * `&amp;lt;a …&amp;gt;`) is stripped as it is decoded, so it never reaches a
 * card as literal tags, while a decoded `<` in prose stays.
 */
export function decodeXmlText(value) {
  let text = String(value || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, ' ');
  for (let pass = 0; pass < 2; pass += 1) {
    const decoded = decodeEntities(text);
    if (decoded === text) break;
    text = decoded.replace(DECODED_TAG, ' ');
  }
  return text.replace(/\s+/g, ' ').trim();
}

const escapeTag = (tag) => tag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** The raw inner text of the first `<tag>` in a block, or ''. */
function rawTag(block, tag) {
  const match = new RegExp(
    `<${escapeTag(tag)}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${escapeTag(tag)}\\s*>`,
    'i',
  ).exec(block);
  return match?.[1] || '';
}

/** The decoded text of the first `<tag>` in a block, or ''. */
export function xmlTag(block, tag) {
  return decodeXmlText(rawTag(block, tag));
}

/** An attribute of the first `<tag …>` in a block, decoded, or ''. */
export function xmlAttr(block, tag, attr, { where = null } = {}) {
  for (const match of String(block || '').matchAll(
    new RegExp(`<${escapeTag(tag)}\\b([^>]*)>`, 'gi'),
  )) {
    const attributes = match[1];
    if (where && !where.test(attributes)) continue;
    const value = new RegExp(
      `\\b${escapeTag(attr)}\\s*=\\s*("([^"]*)"|'([^']*)')`,
      'i',
    ).exec(attributes);
    if (value) return decodeXmlText(value[2] ?? value[3] ?? '');
  }
  return '';
}

/** An http(s) address, resolved against `base` when it is relative; or null. */
export function resolveHttpUrl(value, base = undefined) {
  const text = String(value || '').trim();
  if (!text) return null;
  try {
    const url = base ? new URL(text, base) : new URL(text);
    return url.protocol === 'https:' || url.protocol === 'http:'
      ? url.href
      : null;
  } catch {
    return null;
  }
}

/** The address an element names: its text, or an `<a href>` inside it. */
function elementUrl(block, tag, base) {
  const raw = rawTag(block, tag);
  if (!raw) return null;
  const anchor = /<a\b[^>]*\bhref\s*=\s*["']([^"']+)["']/i.exec(
    raw.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1'),
  )?.[1];
  if (anchor) return resolveHttpUrl(decodeXmlText(anchor), base);
  return resolveHttpUrl(decodeXmlText(raw), base);
}

function dateOrNull(value, timeZone) {
  const text = String(value || '').trim();
  if (!text) return null;
  const ms = Date.parse(text);
  if (Number.isFinite(ms)) return new Date(ms).toISOString();
  if (!timeZone) return null;
  const local = parseLongLocalDate(text, timeZone);
  return Number.isFinite(local) ? new Date(local).toISOString() : null;
}

/** A `georss:point`, `geo:lat`/`geo:long` or `georss:where` position. */
function itemGeo(block) {
  const point = xmlTag(block, 'georss:point');
  if (point) {
    const [lat, lon] = point.split(/[\s,]+/).map(Number);
    if (Number.isFinite(lat) && Number.isFinite(lon)) return { lat, lon };
  }
  const lat = Number(xmlTag(block, 'geo:lat'));
  const lon = Number(xmlTag(block, 'geo:long'));
  if (Number.isFinite(lat) && Number.isFinite(lon) && (lat || lon))
    return { lat, lon };
  return null;
}

/**
 * The items of an RSS 2.0 `<item>` or Atom `<entry>` feed, in feed order:
 * `{ id, title, url, summary, publishedAt, updatedAt, categories, geo }`.
 * Items without a title or an http(s) link are skipped; duplicates (same id
 * or link) are kept once. `baseUrl` resolves relative links when the feed
 * declares no `xml:base`; `timeZone` reads long-form local dates.
 */
export function parseFeedItems(
  xml,
  { limit = 60, baseUrl = undefined, timeZone = null } = {},
) {
  const text = String(xml || '');
  const declaredBase =
    /<(?:rss|feed|channel)\b[^>]*\bxml:base\s*=\s*["']([^"']+)["']/i.exec(
      text,
    )?.[1];
  const base = resolveHttpUrl(declaredBase, baseUrl) || baseUrl;
  const blocks = [
    ...text.matchAll(/<item(?:\s[^>]*)?>([\s\S]*?)<\/item\s*>/gi),
    ...text.matchAll(/<entry(?:\s[^>]*)?>([\s\S]*?)<\/entry\s*>/gi),
  ];
  const seen = new Set();
  const items = [];
  for (const match of blocks) {
    const block = match[1];
    const title = xmlTag(block, 'title').slice(0, 300);
    const url =
      elementUrl(block, 'link', base) ||
      resolveHttpUrl(
        xmlAttr(block, 'link', 'href', {
          where: /rel\s*=\s*["']alternate["']/i,
        }),
        base,
      ) ||
      resolveHttpUrl(xmlAttr(block, 'link', 'href'), base) ||
      null;
    if (!title || !url) continue;
    const guidUrl = elementUrl(block, 'guid', base);
    const guidText = xmlTag(block, 'guid') || xmlTag(block, 'id');
    const id =
      (/<a\b/i.test(rawTag(block, 'guid')) ? guidUrl : guidText) || url;
    if (seen.has(id) || seen.has(url)) continue;
    seen.add(id);
    seen.add(url);
    const summary =
      xmlTag(block, 'description') ||
      xmlTag(block, 'summary') ||
      xmlTag(block, 'content:encoded') ||
      xmlTag(block, 'content');
    const publishedAt =
      dateOrNull(xmlTag(block, 'pubDate'), timeZone) ||
      dateOrNull(xmlTag(block, 'published'), timeZone) ||
      dateOrNull(xmlTag(block, 'dc:date'), timeZone) ||
      dateOrNull(xmlTag(block, 'updated'), timeZone);
    const updatedAt =
      dateOrNull(xmlTag(block, 'updated'), timeZone) ||
      dateOrNull(xmlTag(block, 'atom:updated'), timeZone) ||
      publishedAt;
    const categories = [
      ...block.matchAll(/<category(?:\s[^>]*)?>([\s\S]*?)<\/category\s*>/gi),
    ]
      .map((entry) => decodeXmlText(entry[1]))
      .concat(
        [...block.matchAll(/<category\b([^>]*)\/?>/gi)]
          .map((entry) => /\bterm\s*=\s*["']([^"']*)["']/i.exec(entry[1])?.[1])
          .filter(Boolean)
          .map(decodeXmlText),
      )
      .filter(Boolean)
      .slice(0, 12);
    items.push({
      id,
      title,
      url,
      summary: summary.slice(0, 4000),
      publishedAt,
      updatedAt,
      categories,
      geo: itemGeo(block),
    });
    if (items.length >= limit) break;
  }
  return items;
}

/**
 * Feed addresses an HTML page advertises with
 * `<link rel="alternate" type="application/rss+xml|atom+xml">`, resolved
 * against the page and kept only on the page's own origin, so discovery can
 * never send the proxy to a third-party host.
 */
export function discoverFeedLinks(html, pageUrl) {
  let origin;
  try {
    origin = new URL(pageUrl).origin;
  } catch {
    return [];
  }
  const found = [];
  for (const match of String(html || '').matchAll(/<link\b([^>]*)>/gi)) {
    const attributes = match[1];
    if (!/\brel\s*=\s*["'][^"']*\balternate\b[^"']*["']/i.test(attributes))
      continue;
    if (
      !/\btype\s*=\s*["']application\/(?:rss|atom)\+xml["']/i.test(attributes)
    )
      continue;
    if (/\btitle\s*=\s*["'][^"']*comments/i.test(attributes)) continue;
    const href = /\bhref\s*=\s*["']([^"']+)["']/i.exec(attributes)?.[1];
    if (!href) continue;
    try {
      const url = new URL(decodeXmlText(href), pageUrl);
      if (url.origin !== origin || url.protocol !== 'https:') continue;
      url.hash = '';
      if (!found.includes(url.href)) found.push(url.href);
    } catch {
      /* skip an unparsable href */
    }
  }
  return found;
}
